// /sitemap.xml — generated by Next.js
// Only the list page exists in this prototype skeleton.
// Add a page per internship here if you add detail pages later.
export default function sitemap() {
  const siteUrl =
    process.env.NEXT_PUBLIC_SITE_URL || "https://redolution.example.com";
  return [
    {
      url: siteUrl,
      lastModified: new Date(),
      changeFrequency: "daily",
      priority: 1,
    },
  ];
}
